-- ---------------------------------------------------------------------------
-- 2. CharTitles 200 -- "Paragon %s", the milestone 1000 capstone title.
--
-- Only id 201 ("%s the Pinnacle") was ever written to chartitles_dbc. Title
-- 200 lives solely in the origin box's baked CharTitles.dbc, which is why
-- Tools/paragon_client_patch.py:1722 carries the carve-out comment "Only ids
-- NOT already in the baked file may be listed here (200 is; 201 is not)" --
-- true of that one image, false of every other host.
--
-- Without this row sCharTitlesStore.LookupEntry(200) is null, SetKnownTitle(200)
-- is a silent no-op, and the track still advertises the reward.
--
-- !! Mask_ID 143 IS NOT ARBITRARY -- DO NOT RENUMBER IT !!
-- Mask_ID is a bit index into PLAYER__FIELD_KNOWN_TITLES, and the client's
-- title dropdown iterates mask indexes 1..GetNumTitles(), i.e. the ROW COUNT.
-- Stock masks are dense 1..142 while row ids run sparse to 177, so a gapped
-- mask lands past the end of that loop and never renders -- granted correctly
-- server-side, invisible in the UI. 143 is stock max + 1; 201 takes 144.
-- Constants from Tools/paragon_client_patch.py:1060 (PARAGON_TITLE_ID,
-- PARAGON_TITLE_MASK, PARAGON_TITLE_NAME) and :1061 (LOC_MASK).
-- ---------------------------------------------------------------------------
DELETE FROM `chartitles_dbc` WHERE `ID` = 200;
INSERT INTO `chartitles_dbc`
    (`ID`, `Condition_ID`,
     `Name_Lang_enUS`, `Name_Lang_Mask`,
     `Name1_Lang_enUS`, `Name1_Lang_Mask`,
     `Mask_ID`)
VALUES
    (200, 0, 'Paragon %s', 16712190, 'Paragon %s', 16712190, 143);
